import { Input as BaseInput } from '@base-ui/react/input';
import { useState, type ComponentType, type ReactNode, type Ref } from 'react';
import { useRender } from '@base-ui/react/use-render';
import { ClearControlButton, resetNativeValue, type ClearableProps } from '../../utils/clear-control';
import { useFieldVariant } from '../../field-variant/field-variant-context';
import { cn } from '../../utils/cn';
import { inputVariants, INPUT_ICON_SIZE, type InputVariantProps } from './input.variants';

type IconComponent = ComponentType<{ size?: number; 'aria-hidden'?: boolean; className?: string }>;

export interface InputProps extends Omit<BaseInput.Props, 'className' | 'size'>, InputVariantProps, ClearableProps {
  /** Clear a non-empty editable input on Escape and stop propagation. */
  clearOnEscape?: boolean;
  /** Classes for the outer wrapper (border, width, layout). */
  className?: string;
  /** Classes for the native <input>. */
  inputClassName?: string;
  ref?: Ref<HTMLInputElement>;
  /** Decorative icon before the text (a lucide icon component). */
  leadingIcon?: IconComponent;
  /** Decorative icon after the text. */
  trailingIcon?: IconComponent;
  /** Content before the input: a text prefix ("https://") or a compact control. */
  leadingAddon?: ReactNode;
  /** Content after the input: a unit ("req/s"), a keyboard hint or an icon button. */
  trailingAddon?: ReactNode;
  /** Marks the value as invalid (sets aria-invalid). Inside a Field, `Field invalid` does this. */
  invalid?: boolean;
}

/**
 * Single-line text input on Base UI Input (works with Field out of the box). The wrapper
 * carries the border, focus outline and invalid/disabled styling; icons and addons sit inside it.
 */
export function Input({
  size = 'auto',
  variant,
  className,
  inputClassName,
  leadingIcon: LeadingIcon,
  trailingIcon: TrailingIcon,
  leadingAddon,
  trailingAddon,
  invalid,
  clearable,
  clearLabel,
  onClear,
  clearOnEscape,
  ref,
  onValueChange,
  onKeyDown,
  ...props
}: InputProps) {
  const fieldVariant = useFieldVariant(variant);
  const [control, setControl] = useState<HTMLInputElement | null>(null);
  const [inner, setInner] = useState(props.defaultValue ?? '');
  const hasValue = String(props.value ?? (control ? control.value : inner)).length > 0;
  const clear = () => {
    if (!control || control.disabled || control.readOnly) return;
    resetNativeValue(control);
    onClear?.();
    control.focus();
  };
  const input = useRender({
    ref: [ref ?? null, setControl],
    render: (
      <BaseInput
        {...props}
        onValueChange={(value, details) => {
          setInner(value);
          onValueChange?.(value, details);
        }}
        onKeyDown={(event) => {
          onKeyDown?.(event);
          if (
            !event.defaultPrevented &&
            clearOnEscape &&
            event.key === 'Escape' &&
            event.currentTarget.value &&
            !event.currentTarget.disabled &&
            !event.currentTarget.readOnly
          ) {
            event.preventDefault();
            event.stopPropagation();
            clear();
          }
        }}
        className={cn(inputVariants({ size, variant: fieldVariant }).input(), inputClassName)}
        aria-invalid={props['aria-invalid'] ?? (invalid || undefined)}
      />
    ),
  });
  const s = inputVariants({ size, variant: fieldVariant });
  const px = INPUT_ICON_SIZE[size];
  return (
    <div className={cn(s.root(), className)} data-invalid={invalid || undefined}>
      {LeadingIcon && <LeadingIcon size={px} aria-hidden className={s.icon()} />}
      {leadingAddon != null && <span className={s.addon()}>{leadingAddon}</span>}
      {input}
      {trailingAddon != null && <span className={s.addon()}>{trailingAddon}</span>}
      {clearable && hasValue && !props.disabled && !props.readOnly && (
        <ClearControlButton control={control} clearLabel={clearLabel} onClick={clear} />
      )}
      {TrailingIcon && <TrailingIcon size={px} aria-hidden className={s.icon()} />}
    </div>
  );
}

/** Keyboard-shortcut hint for a trailing addon, e.g. `<InputKbd>⌘K</InputKbd>`. */
export function InputKbd({ className, children }: { className?: string; children: ReactNode }) {
  return (
    <kbd
      className={cn(
        'inline-flex h-[18px] items-center rounded border border-border bg-card px-1.5 font-mono text-[10px] font-medium text-muted-foreground',
        className,
      )}
    >
      {children}
    </kbd>
  );
}

export { Input, InputKbd, type InputProps } from './Input';
export { inputVariants, INPUT_ICON_SIZE, type InputVariantProps } from './input.variants';
export { doc as inputDoc } from './Input.doc';

import { fieldControlVariants } from '../../field-variant/field-control-variants';
import { tv, type VariantProps } from '../../utils/tv';

/**
 * The brand field: a recessed (bg-background) wrapper that owns the border and the focus
 * outline, so icons, addons and the bare input focus as one piece.
 */
export const inputVariants = tv({
  slots: {
    root: [
      'flex w-full min-w-0 items-center rounded-md border border-border bg-background text-foreground shadow-sm transition-colors motion-reduce:transition-none',
      'has-[input:focus-visible]:border-primary/60 has-[input:focus-visible]:outline-2 has-[input:focus-visible]:outline-offset-2 has-[input:focus-visible]:outline-focus-ring',
      'data-invalid:border-destructive/70 has-[input[data-invalid]]:border-destructive/70 has-[input[aria-invalid=true]]:border-destructive/70',
      'has-[input:disabled]:cursor-disabled has-[input:disabled]:bg-secondary/50 has-[input:disabled]:text-muted-foreground',
      'has-[input:read-only]:bg-secondary/40',
    ],
    input: [
      'h-full w-full min-w-0 bg-transparent text-foreground outline-none placeholder:text-muted-foreground',
      'disabled:cursor-disabled disabled:text-muted-foreground read-only:text-muted-foreground',
    ],
    icon: 'pointer-events-none shrink-0 text-muted-foreground',
    addon: 'flex shrink-0 items-center text-muted-foreground select-none',
  },
  variants: {
    variant: {
      outline: {},
      filled: { root: fieldControlVariants.filled },
      ghost: { root: fieldControlVariants.ghost },
    },
    size: {
      /** Follows `data-density` (comfortable = md). */
      auto: { root: 'h-control gap-tight px-field text-[13px]', input: 'text-[13px]' },
      sm: { root: 'h-8 gap-2 px-2.5 text-[12px]', input: 'text-[12px]' },
      md: { root: 'h-9 gap-2.5 px-3 text-[13px]', input: 'text-[13px]' },
    },
  },
  defaultVariants: { variant: 'outline', size: 'auto' },
});

export type InputVariantProps = VariantProps<typeof inputVariants>;

/** Icon size (px) per input size. */
export const INPUT_ICON_SIZE = { auto: 15, sm: 14, md: 15 } as const;

/** Only alternate chrome overrides the existing outline classes. Forced colours retain a boundary. */
export const fieldControlVariants = {
  outline: '',
  filled: 'border-transparent bg-secondary shadow-none forced-colors:border-[ButtonText]',
  ghost: 'border-transparent bg-transparent shadow-none hover:bg-secondary/50 forced-colors:border-[ButtonText]',
} as const;

/** Picker hover must not mask a keyboard-focus, open-popup or error border. */
export const fieldPickerHover =
  'hover:border-transparent hover:focus-visible:border-primary/60 hover:data-popup-open:border-primary/60 hover:data-invalid:border-destructive/70 hover:aria-invalid:border-destructive/70';

import { createContext, useContext } from 'react';

/** Field chrome; outline preserves the original bordered appearance. */
export type FieldControlVariant = 'outline' | 'filled' | 'ghost';
export const FieldVariantContext = createContext<FieldControlVariant>('outline');

/** Explicit props win over the nearest provider, then the outline default. */
export function useFieldVariant(variant?: FieldControlVariant): FieldControlVariant {
  const inherited = useContext(FieldVariantContext);
  return variant ?? inherited;
}

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
